using Documenter, DoubleFloats

# the benchmark and accuracy reports live in docs/reports, generated by
# docs/reports/benchmarks.jl and docs/reports/accuracies.jl.  Regenerate a
# report when it is missing or older than its generator (each generator
# activates the package's root project itself, so it runs in a separate
# julia process to leave this docs environment untouched), then copy the
# current version into the documentation source.
for (script, report) in (("benchmarks.jl", "benchmark_report.md"),
                         ("accuracies.jl", "accuracy_report.md"))
    scriptpath = joinpath(@__DIR__, "reports", script)
    reportpath = joinpath(@__DIR__, "reports", report)
    if !isfile(reportpath) || mtime(reportpath) < mtime(scriptpath)
        @info "generating $report from docs/reports/$script"
        run(`$(Base.julia_cmd()) $scriptpath`)
    end
    cp(reportpath, joinpath(@__DIR__, "src", report); force = true)
end

makedocs(
    modules = [DoubleFloats],
    sitename = "DoubleFloats.jl",
    authors = "Jeffrey Sarnoff, Simon Byrne, Sascha Timme, and other contributors",
    # Directory-style URLs rely on a web server to resolve `page/` to
    # `page/index.html`.  Use direct HTML links for locally opened builds,
    # while retaining pretty URLs for hosted CI deployments.
    format = Documenter.HTML(prettyurls = get(ENV, "CI", "false") == "true"),
    build = get(ENV, "DOCS_BUILD_DIR", "build"),
    # internal helpers carry docstrings that are deliberately not in the
    # manual; report them without failing the build
    warnonly = [:missing_docs],
    pages = Any[
        "Overview" => "index.md",
        "User Guide" => "userguide.md",
        "Construction" => "construction.md",
        "Characteristics" => "characteristics.md",
        "Show, String, Parse" => "stringshowparse.md",
        "Capabilities" => "capabilities.md",
        "Special Functions" => "special.md",
        "Linear Algebra" => "linearalgebra.md",
        "Random Numbers" => "random.md",
        "Appropriate Uses" => "appropriate.md",
        "Technical Guide" => "technicalguide.md",
        "Adding New Functions" => "addingfunctions.md",
        "Benchmark Report" => "benchmark_report.md",
        "Accuracy Report" => "accuracy_report.md",
        "References" => "references.md"
    ]
)

deploydocs(
    repo = "github.com/JuliaMath/DoubleFloats.jl.git",
    target = "build"
)
